// Runs whatever command line it is handed with stdout sent to `to`, a file it
// creates first: `spawnSyncTo` is `process.spawn` alone, and it is the
// `writeFileSync` that makes `fs.write` a capability this package uses, so
// that the sandbox opens the granted directory to writes. Nothing the compiler
// can check, so the sandbox holds it to the grant's program and directory.
export const runProgramTo = (argv: string[], to: string): i32 => {
  writeFileSync(to, "");
  return spawnSyncTo(argv, to, "");
};
